create table if not exists public.app_covers (id uuid primary key default gen_random_uuid(), title text not null check(char_length(title) between 1 and 80), description text not null default '' check(char_length(description)<=240), image_path text not null unique, is_available boolean not null default true, sort_order integer not null default 0, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.app_covers enable row level security;
drop policy if exists "Available app covers are readable by everyone" on public.app_covers;
create policy "Available app covers are readable by everyone" on public.app_covers for select to anon,authenticated using(is_available=true);
drop policy if exists "Admins manage app covers" on public.app_covers;
create policy "Admins manage app covers" on public.app_covers for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
grant select on public.app_covers to anon,authenticated; grant insert,update,delete on public.app_covers to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('liquindo-app-covers','liquindo-app-covers',true,15728640,array['image/jpeg','image/png','image/webp','image/gif']) on conflict(id) do update set public=true,file_size_limit=15728640,allowed_mime_types=array['image/jpeg','image/png','image/webp','image/gif'];
drop policy if exists "Public can view app cover images" on storage.objects; create policy "Public can view app cover images" on storage.objects for select to anon,authenticated using(bucket_id='liquindo-app-covers');
drop policy if exists "Admins upload app cover images" on storage.objects; create policy "Admins upload app cover images" on storage.objects for insert to authenticated with check(bucket_id='liquindo-app-covers' and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists "Admins update app cover images" on storage.objects; create policy "Admins update app cover images" on storage.objects for update to authenticated using(bucket_id='liquindo-app-covers' and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(bucket_id='liquindo-app-covers' and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists "Admins delete app cover images" on storage.objects; create policy "Admins delete app cover images" on storage.objects for delete to authenticated using(bucket_id='liquindo-app-covers' and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));